9	  <title>Circle Display</title>
10	  <style>
11	    :root {
12	      --color-white: #ffffff;
13	      --color-gold: #ffd700;
14	      --color-pink: #ff6b9d;
15	      --color-teal: #4ecdc4;
16	      --color-mint: #95e1d3;
17	      --shadow-color: rgba(0, 0, 0, 0.3);
18	      --transition-normal: 0.3s ease;
19	      --transition-slow: 0.6s ease-out;
20	      --color-mode-1-rgb: 255, 107, 157;
21	      --color-mode-2-rgb: 78, 205, 196;
22	      --color-mode-3-rgb: 149, 225, 211;
23	    }
24	
25	    * {
26	      margin: 0;
27	      padding: 0;
28	      box-sizing: border-box;
29	    }
30	    html, body {
31	      width: 100%;
32	      height: 100%;
33	      overflow: hidden;
34	    }
35	    body {
36	      display: flex;
37	      flex-direction: column;
38	      justify-content: center;
39	      align-items: center;
40	      gap: 20px;
41	      background: linear-gradient(135deg, #5f6fd1 0%, #6b3fa0 100%);
42	      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
43	      color: var(--color-white);
44	      font-size: 14px;
45	      padding: 20px;
46	      min-height: 100vh;
47	    }
48	    .circle-container {
49	      cursor: pointer;
50	      border: none;
51	      background: none;
52	      padding: 0;
53	      position: relative;
54	      will-change: transform;
55	      contain: layout style paint;
56	    }
57	    .circle-container:hover {
58	      transform: scale(1.05);
59	    }
60	    .circle-container:focus {
61	      outline: none;
62	    }
63	    .circle-container:focus-visible {
64	      transform: scale(1.08);
65	      outline: 3px solid rgba(255, 255, 255, 0.7);
66	      outline-offset: 12px;
67	      border-radius: 50%;
68	    }
69	    svg {
70	      width: min(400px, 80vw);
71	      height: min(400px, 80vw);
72	      display: block;
73	      animation: fadeIn var(--transition-slow);
74	    }
75	    circle {
76	      fill: var(--color-white);
77	      stroke: rgba(255, 255, 255, 0.25);
78	      stroke-width: 1.5;
79	      animation: pulse 3s ease-in-out infinite;
80	      filter: drop-shadow(0 20px 40px var(--shadow-color));
81	      transition: fill 0.3s ease, r 0.3s ease, stroke 0.3s ease, filter 0.3s ease;
82	      will-change: r, fill, filter;
83	    }
84	    .circle-container:is(:hover, :focus-visible) circle {
85	      fill: #e8f4f8;
86	      r: 205;
87	      stroke: rgba(255, 255, 255, 0.4);
88	    }
89	    .circle-container.active circle {
90	      fill: var(--color-gold);
91	      stroke: rgba(255, 215, 0, 0.3);
92	      animation: pulse-active 0.6s ease-in-out;
93	      filter: drop-shadow(0 20px 40px rgba(255, 215, 0, 0.5));
94	      r: 200;
95	    }
96	
97	    [class*="color-mode-"] circle {
98	      fill: var(--mode-color);
99	      stroke: rgba(var(--mode-rgb), 0.3);
100	      filter: drop-shadow(0 20px 40px rgba(var(--mode-rgb), 0.3));
101	    }
102	    [class*="color-mode-"]:is(:hover, :focus-visible) circle {
103	      stroke: rgba(var(--mode-rgb), 0.5);
104	    }
105	    [class*="color-mode-"].active circle {
106	      filter: drop-shadow(0 20px 40px rgba(var(--mode-rgb), 0.5));
107	    }
108	
