110	    .circle-container.color-mode-2 { --mode-color: var(--color-teal); --mode-rgb: var(--color-mode-2-rgb); }
111	    .circle-container.color-mode-3 { --mode-color: var(--color-mint); --mode-rgb: var(--color-mode-3-rgb); }
112	
113	    .hint {
114	      font-size: 12px;
115	      opacity: 0.9;
116	      transition: opacity var(--transition-normal);
117	      letter-spacing: 0.5px;
118	      max-width: 90%;
119	      line-height: 1.6;
120	      margin-top: 12px;
121	      position: relative;
122	      text-shadow: 0 2px 8px rgba(0, 0, 0, 0.5);
123	      will-change: opacity;
124	    }
125	
126	    .mode-indicator {
127	      font-size: 10px;
128	      opacity: 0;
129	      margin-top: 8px;
130	      letter-spacing: 1px;
131	      text-transform: uppercase;
132	      transition: opacity var(--transition-normal);
133	      height: 16px;
134	    }
135	    .mode-indicator.visible {
136	      opacity: 0.9;
137	    }
