148	    .control-btn {
149	      padding: 10px 20px;
150	      font-size: 12px;
151	      font-weight: 600;
152	      letter-spacing: 0.8px;
153	      text-transform: uppercase;
154	      background: rgba(255, 255, 255, 0.18);
155	      color: var(--color-white);
156	      border: 1.5px solid rgba(255, 255, 255, 0.35);
157	      border-radius: 24px;
158	      cursor: pointer;
159	      transition: background-color var(--transition-normal), border-color var(--transition-normal), transform var(--transition-normal), box-shadow var(--transition-normal);
160	      backdrop-filter: blur(4px);
161	      will-change: transform;
162	      outline: none;
163	    }
164	
165	    .control-btn:hover {
166	      background: rgba(255, 255, 255, 0.28);
167	      border-color: rgba(255, 255, 255, 0.6);
168	      transform: translateY(-3px);
169	      box-shadow: 0 10px 20px rgba(0, 0, 0, 0.25);
170	    }
171	
172	    .control-btn:active {
173	      transform: translateY(0) scale(0.96);
174	      box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
175	    }
176	
177	    .control-btn:focus-visible {
178	      outline: 2px solid rgba(255, 255, 255, 0.7);
179	      outline-offset: 4px;
180	    }
181	    .control-btn:disabled {
182	      opacity: 0.5;
183	      cursor: not-allowed;
184	    }
185	    @keyframes pulse {
186	      0%, 100% { r: 200; opacity: 0.95; }
187	      50% { r: 203; opacity: 1; }
188	    }
189	    @keyframes pulse-active {
190	      0% { r: 200; }
191	      50% { r: 210; }
192	      100% { r: 200; }
193	    }
194	    @keyframes fadeIn {
195	      from { opacity: 0; transform: scale(0.9); }
196	      to { opacity: 1; transform: scale(1); }
197	    }
198	    @keyframes colorShift {
199	      0% { filter: saturate(1) brightness(1); }
200	      50% { filter: saturate(1.3) brightness(1.1); }
201	      100% { filter: saturate(1) brightness(1); }
202	    }
203	    .color-shifting circle {
204	      animation: colorShift 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
205	      transform-origin: center;
206	    }
207	    .keyboard-hint {
208	      font-size: 10px;
209	      opacity: 0.6;
210	      margin-top: 6px;
211	      letter-spacing: 0.3px;
212	      transition: opacity var(--transition-normal);
213	    }
214	    .keyboard-hint kbd {
215	      background: rgba(255, 255, 255, 0.15);
216	      border: 1px solid rgba(255, 255, 255, 0.25);
217	      border-radius: 3px;
218	      padding: 2px 6px;
219	      font-family: 'Monaco', 'Courier New', monospace;
220	      font-size: 9px;
221	      font-weight: 500;
222	      display: inline-block;
223	      margin: 0 2px;
224	    }
225	    @media (pointer: coarse) {
226	      .keyboard-hint {
227	        display: none;
228	      }
229	    }
230	    main {
231	      display: flex;
232	      flex-direction: column;
233	      align-items: center;
234	      justify-content: center;
235	      gap: 12px;
236	      text-align: center;
237	      width: 100%;
238	      flex: 1;
239	    }
