241	    @media (max-width: 480px) {
242	      body {
243	        gap: 12px;
244	        padding: 16px;
245	      }
246	      svg {
247	        width: min(320px, 75vw);
248	        height: min(320px, 75vw);
249	      }
250	      .hint {
251	        font-size: 11px;
252	        max-width: 90%;
253	        margin-top: 10px;
254	      }
255	      .mode-indicator {
256	        font-size: 9px;
257	      }
258	      .control-btn {
259	        padding: 12px 20px;
260	        font-size: 11px;
261	        min-height: 44px;
262	        display: flex;
