264	        justify-content: center;
265	      }
266	    }
267	    @media (max-width: 360px) {
268	      body {
269	        gap: 8px;
270	        padding: 12px;
271	      }
272	      svg {
273	        width: min(280px, 70vw);
274	        height: min(280px, 70vw);
275	      }
276	      .controls {
277	        flex-wrap: wrap;
278	      }
279	      .mode-indicator {
280	        font-size: 10px;
