283	        font-size: 9px;
284	      }
285	      .keyboard-hint kbd {
286	        padding: 3px 6px;
287	        font-size: 8px;
288	      }
289	    }
290	    @media (prefers-reduced-motion: reduce) {
291	      * {
292	        animation: none !important;
293	        transition: none !important;
294	      }
295	    }
296	    @supports (backdrop-filter: blur(0)) {
297	      .control-btn {
298	        background: rgba(255, 255, 255, 0.1);
299	      }
