328	<body>
329	  <main>
330	    <button class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to toggle" aria-pressed="false">
331	      <svg viewBox="0 0 400 400" aria-hidden="true" role="presentation">
332	        <circle cx="200" cy="200" r="200"/>
333	      </svg>
334	    </button>
335	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true" aria-label="Current color mode"></div>
336	    <div class="controls" role="group" aria-label="Circle controls">
337	      <button class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
338	      <button class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
339	    </div>
340	  </main>
341	  <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click to activate • Double-click to change color</div>
342	  <div class="keyboard-hint" aria-label="Keyboard shortcuts: Space or Enter to toggle, C to cycle color, R to reset">Press <kbd>C</kbd> to cycle • <kbd>R</kbd> to reset</div>
343	
344	  <script>
345	    const CONFIG = {
346	      storageKey: 'circle-state',
347	      tapDelay: 300,
348	      colorShiftDuration: 500,
349	      colorModes: [
350	        { class: 'default', name: 'Default White' },
351	        { class: 'color-mode-1', name: 'Pink' },
352	        { class: 'color-mode-2', name: 'Teal' },
353	        { class: 'color-mode-3', name: 'Mint' }
354	      ],
355	      isTouch: 'ontouchstart' in window || navigator.maxTouchPoints > 0
356	    };
357	
358	    const el = {
359	      circle: document.getElementById('decorative-circle'),
360	      hint: document.getElementById('hint-text'),
361	      modeIndicator: document.getElementById('mode-indicator'),
362	      cycleBtn: document.getElementById('cycle-btn'),
363	      resetBtn: document.getElementById('reset-btn')
364	    };
365	
366	    let state = { active: false, colorMode: 0 };
367	    let lastTapTime = 0;
368	    let tapTimeout = null;
369	    let animatingColorShift = false;
370	
371	    const getColorModeClass = (mode) => CONFIG.colorModes[mode].class;
372	    const getColorModeName = (mode) => CONFIG.colorModes[mode].name;
373	
374	    const storage = {
375	      save() {
376	        try {
377	          localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
378	        } catch {
379	          // Silently fail if localStorage is unavailable or quota exceeded
380	        }
381	      },
382	      load() {
383	        try {
384	          const saved = localStorage.getItem(CONFIG.storageKey);
385	          if (saved) {
386	            const parsed = JSON.parse(saved);
387	            if (parsed && typeof parsed === 'object') {
388	              state = { ...state, ...parsed };
389	            }
390	          }
391	        } catch {
392	          // Silently fail if parsing fails
393	        }
394	      }
395	    };
396	
397	    const updateClasses = () => {
398	      const colorClasses = CONFIG.colorModes.map(m => m.class);
399	      el.circle.classList.remove('active', ...colorClasses);
400	      el.circle.setAttribute('aria-pressed', state.active);
401	      if (state.active) el.circle.classList.add('active');
402	      if (state.colorMode > 0) el.circle.classList.add(getColorModeClass(state.colorMode));
403	    };
404	
405	    const updateUI = () => {
406	      const mainText = state.active ? 'Active!' : 'Click to activate';
407	      let hintParts = [mainText];
408	
409	      if (CONFIG.isTouch) {
410	        hintParts.push(state.active ? 'Tap to change color' : 'Tap twice to change color');
411	      } else {
412	        hintParts.push('Double-click to change color');
413	      }
414	
415	      el.hint.textContent = hintParts.join(' • ');
416	
417	      const showMode = state.active && state.colorMode > 0;
418	      el.modeIndicator.classList.toggle('visible', showMode);
419	      if (showMode) {
420	        const modeName = getColorModeName(state.colorMode);
421	        el.modeIndicator.textContent = modeName;
422	      }
423	    };
424	
425	    const applyState = () => {
426	      updateClasses();
427	      updateUI();
428	    };
429	
430	    const toggleActive = () => {
431	      state.active = !state.active;
432	      applyState();
433	      storage.save();
434	    };
435	
436	    const cycleColor = () => {
437	      if (animatingColorShift) return;
438	      animatingColorShift = true;
439	      state.colorMode = (state.colorMode + 1) % CONFIG.colorModes.length;
440	      state.active = true;
441	      el.circle.classList.add('color-shifting');
442	      setTimeout(() => {
443	        el.circle.classList.remove('color-shifting');
444	        animatingColorShift = false;
445	      }, CONFIG.colorShiftDuration);
446	      applyState();
447	      storage.save();
448	    };
449	
450	    const resetState = () => {
451	      state = { active: false, colorMode: 0 };
452	      applyState();
453	      storage.save();
454	    };
455	
456	    const handleDblClick = (e) => {
457	      e.preventDefault();
458	      cycleColor();
459	    };
460	
461	    const handleTouchEnd = (e) => {
462	      const now = Date.now();
463	      if (now - lastTapTime < CONFIG.tapDelay && lastTapTime > 0) {
464	        cycleColor();
465	        lastTapTime = 0;
466	        clearTimeout(tapTimeout);
467	      } else {
468	        lastTapTime = now;
469	        clearTimeout(tapTimeout);
470	        tapTimeout = setTimeout(() => { lastTapTime = 0; }, CONFIG.tapDelay);
471	      }
472	    };
473	
474	    const keyHandlers = {
475	      ' ': toggleActive,
476	      'enter': toggleActive,
477	      'c': cycleColor,
478	      'r': resetState
479	    };
480	
481	    const handleKeyDown = (e) => {
482	      const handler = keyHandlers[e.key.toLowerCase()];
483	      if (handler) {
484	        e.preventDefault();
485	        handler();
486	      }
487	    };
488	
489	    const initListeners = () => {
490	      el.circle.addEventListener('click', toggleActive);
491	      el.circle.addEventListener('dblclick', handleDblClick);
492	      el.circle.addEventListener('touchend', handleTouchEnd);
493	      el.circle.addEventListener('blur', () => {
494	        lastTapTime = 0;
495	        clearTimeout(tapTimeout);
496	      });
497	      document.addEventListener('keydown', handleKeyDown);
498	      el.cycleBtn.addEventListener('click', cycleColor);
499	      el.resetBtn.addEventListener('click', resetState);
500	    };
501	
502	    const initApp = () => {
503	      storage.load();
504	      applyState();
505	      initListeners();
506	      requestAnimationFrame(() => el.circle.focus());
507	    };
508	
509	    if (document.readyState === 'loading') {
510	      document.addEventListener('DOMContentLoaded', initApp);
511	    } else {
512	      initApp();
513	    }
514	  </script>
515	</body>
516	</html>
